// wNumb fallback - minimal number formatting
(function() {
    'use strict';
    
    function wNumb(options) {
        const settings = Object.assign({
            decimals: 2,
            thousand: ',',
            decimal: '.',
            prefix: '',
            suffix: ''
        }, options);
        
        return {
            to: function(value) {
                if (typeof value !== 'number') return value;
                
                const parts = value.toFixed(settings.decimals).split('.');
                parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, settings.thousand);
                
                return settings.prefix + parts.join(settings.decimal) + settings.suffix;
            },
            from: function(value) {
                if (typeof value !== 'string') return value;
                
                return parseFloat(value.replace(/[^\d.-]/g, '')) || 0;
            }
        };
    }
    
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = wNumb;
    } else {
        window.wNumb = wNumb;
    }
})();
